// Winx Sun & Moon fairy wings (Stella-inspired). Mirrored about x=128, thin sculpted Z depth, grounded at Y=0.
var G = {};
var CX = 128, CZ = 128;
function S(u, y, z, t) { // mirrored set; u = distance from centre along X
  u = Math.round(u); y = Math.round(y); z = Math.round(z);
  G[(CX + u) + ',' + y + ',' + z] = t;
  G[(CX - u) + ',' + y + ',' + z] = t;
}
function col(u, y, zc, h, t) { // vertical-in-Z column of thickness 2h around zc
  var a = Math.round(zc - h), b = Math.round(zc + h);
  if (b < a) b = a;
  for (var z = a; z <= b; z++) S(u, y, z, t);
}
function sweep(u, v) { return CZ + 0.0026 * u * u + 0.00045 * Math.max(0, v - 60) * u; } // wings sweep back & curve
var D2R = Math.PI / 180;

// ---------------- UPPER WINGS: golden sun-ray fans ----------------
var UR = { u: 5, v: 78 };
var TH0 = 6, TH1 = 82, NR = 9;
var rays = [];
for (var i = 0; i < NR; i++) {
  var th = TH0 + 4 + (TH1 - TH0 - 8) * i / (NR - 1);
  rays.push({ th: th, L: (i % 2 === 0 ? 30 : 17) * (i === 0 ? 0.7 : 1) * (i === NR - 1 ? 0.85 : 1), w: i % 2 === 0 ? 4.6 : 3.6 });
}
var spacing = (TH1 - TH0 - 8) / (NR - 1);
function baseR(th) { // rounded fan envelope
  var e = Math.min(th - TH0, TH1 - th);
  if (e < 0) return 0;
  var round = Math.min(1, e / 7);
  return (40 + 6 * Math.sin((th - TH0) / (TH1 - TH0) * Math.PI)) * Math.sqrt(round);
}
function spikeR(th) {
  var best = 0, bi = -1;
  for (var k = 0; k < rays.length; k++) {
    var d = Math.abs(th - rays[k].th);
    var s = rays[k].L * Math.max(0, 1 - d / rays[k].w);
    if (s > best) { best = s; bi = k; }
  }
  return { s: best, k: bi };
}
for (var u = 0; u <= 125; u++) for (var v = 60; v <= 170; v++) {
  var dx = u - UR.u, dy = v - UR.v;
  var r = Math.sqrt(dx * dx + dy * dy);
  var th = Math.atan2(dy, dx) / D2R;
  if (th < TH0 - 2 || th > TH1 + 2) continue;
  var Rb = baseR(th);
  if (Rb <= 0) continue;
  var sp = spikeR(th);
  var Rt = Rb + sp.s;
  if (r > Rt || r < 3) continue;
  // nearest vein
  var phase = (th - rays[0].th) / spacing;
  var fr = phase - Math.round(phase);
  var arcToVein = Math.abs(fr) * spacing * D2R * r;
  var billow = 1.6 * Math.pow(Math.sin(Math.PI * fr), 2) * Math.min(1, r / 20);
  var zc = sweep(u, v) + billow;
  var edgeDist = Rt - r;
  var taper = Math.max(0.5, 1 - r / 130);
  var t, h;
  var inSpike = r > Rb - 1;
  var sector = Math.floor(phase + 100) % 2;
  if (inSpike) zc -= 0.12 * (r - Rb); // spike tips curl forward
  if (inSpike && sp.s > 2 && r > Rb + sp.s * 0.72) { t = 'glowstone'; h = 0.9; }
  else if (edgeDist < 1.8) { t = inSpike && sp.s > 2 ? 'orange_wool' : 'gold_block'; h = 1.2 * taper; }
  else if (arcToVein < 0.8 && r > 8) { t = inSpike ? 'gold_block' : 'glowstone'; h = 1.6 * taper; zc -= 0.3; }
  else if (Math.abs(r - Rb * 0.52) < 1.0) { t = 'orange_wool'; h = 1.4 * taper; }
  else if (Math.abs(r - Rb * 0.80) < 0.8) { t = 'gold_block'; h = 1.2 * taper; }
  else if (inSpike) { t = (edgeDist < 3.2) ? 'orange_wool' : 'yellow_wool'; h = 0.8; }
  else {
    var q = r / Rb + (rng() - 0.5) * 0.08;
    if (q < 0.3) t = 'glowstone';
    else if (q > 0.8) t = sector ? 'orange_wool' : 'gold_block';
    else t = sector ? 'gold_block' : 'yellow_wool';
    h = 0.55;
  }
  col(u, v, zc, h, t);
}

// ---------------- LOWER WINGS: silvery-blue crescent moons ----------------
var C1 = { u: 34, v: 38 }, R1 = 34, VS = 1.1;
var offA = -25 * D2R, OFF = 16, R2 = 31;
var C2 = { u: C1.u + OFF * Math.cos(offA), v: C1.v + OFF * Math.sin(offA) * VS };
var moonRibs = [];
for (var a = 62; a <= 262; a += 20) moonRibs.push(a);
for (var u = 0; u <= 90; u++) for (var v = 0; v <= 100; v++) {
  var px = u - C1.u, py = (v - C1.v) / VS;
  var r1 = Math.sqrt(px * px + py * py);
  if (r1 > R1) continue;
  var qx = u - C2.u, qy = (v - C2.v) / VS;
  var r2 = Math.sqrt(qx * qx + qy * qy);
  if (r2 < R2) continue;
  var outerE = R1 - r1, innerE = r2 - R2;
  var tt = innerE / (innerE + outerE + 1e-6); // 0 inner concave edge .. 1 outer convex edge
  var ang = Math.atan2(py, px) / D2R; if (ang < 0) ang += 360;
  var ribD = 999;
  for (var k = 0; k < moonRibs.length; k++) ribD = Math.min(ribD, Math.abs(ang - moonRibs[k]) * D2R * r1);
  var thick = Math.min(innerE + outerE, 20);
  var zc = sweep(u, v) + 1.8 * Math.sin(Math.PI * tt) * Math.min(1, thick / 10); // concave dish
  var taper = Math.max(0.45, Math.min(1, thick / 12));
  var t, h;
  if (outerE < 1.7) { t = 'iron_block'; h = 1.4 * taper; }
  else if (innerE < 1.5) { t = 'blue_wool'; h = 1.2 * taper; }
  else if (ribD < 0.9 && tt > 0.15) { t = 'iron_block'; h = 1.4 * taper; }
  else if (tt < 0.3 + (rng() - 0.5) * 0.08) { t = 'blue_wool'; h = 0.6; }
  else if (tt > 0.4 && tt < 0.72 && thick > 9) { t = 'glass'; h = 0.5; }
  else { t = 'white_wool'; h = 0.6; }
  col(u, v, zc, h, t);
}

// ---------------- STAR ORNAMENTS ----------------
function star(cu, cv, R, rot, core, tipT, bodyT) {
  var zc0 = sweep(cu, cv);
  for (var du = -R - 1; du <= R + 1; du++) for (var dv = -R - 1; dv <= R + 1; dv++) {
    var rr = Math.sqrt(du * du + dv * dv);
    var ph = ((Math.atan2(dv, du) / D2R - rot) % 72 + 72) % 72;
    var lim = R * 0.42 + R * 0.58 * Math.max(0, 1 - Math.abs(ph - 36) / 36);
    if (rr > lim + 0.3) continue;
    var h = 1.4 * (1 - rr / (R + 1)) + 0.5;
    var t = rr < R * 0.3 ? core : (rr > lim - 1.0 ? tipT : bodyT);
    col(cu + du, cv + dv, zc0, h, t);
  }
}
// sun stars in the valleys between long rays
for (var i = 1; i < NR - 1; i++) {
  if (i % 2 === 1) {
    var th = rays[i].th, rr = baseR(th) + rays[i].L + 1.5;
    star(UR.u + rr * Math.cos(th * D2R), UR.v + rr * Math.sin(th * D2R), i === 3 || i === 5 ? 4.5 : 3.6, 90, 'glowstone', 'gold_block', 'yellow_wool');
  }
}
// moon stars nestled inside the crescent's concave edge
var mstars = [[-38, 3.4], [-8, 4.4], [22, 3.6]];
for (var i = 0; i < mstars.length; i++) {
  var a2 = (offA / D2R) + 180 + mstars[i][0];
  var rr = R2 - mstars[i][1] + 1.2;
  var su = C2.u + rr * Math.cos(a2 * D2R), sv = C2.v + rr * Math.sin(a2 * D2R) * VS;
  star(su, sv, mstars[i][1], 90 + i * 11, 'glowstone', 'iron_block', 'white_wool');
}
// a tiny star on each lower-crescent tip & upper spike base
// ---------------- CENTRE EMBLEM: sun disc cradled by crescent moon ----------------
var EV = 70;
// crescent cradle (opens upward), lens-thick
for (var u = 0; u <= 20; u++) for (var v = EV - 22; v <= EV + 6; v++) {
  var a1 = Math.sqrt(u * u + (v - (EV - 3)) * (v - (EV - 3)));
  var a2 = Math.sqrt(u * u + (v - (EV + 3)) * (v - (EV + 3)));
  if (a1 > 17 || a2 < 15.5) continue;
  var th2 = Math.min(17 - a1, a2 - 15.5);
  var t = (17 - a1) < 1.3 ? 'iron_block' : (a2 - 15.5) < 1.2 ? 'blue_wool' : 'white_wool';
  col(u, v, CZ + 0.6, 1.2 + Math.min(2.2, th2 * 0.5), t);
}
// sun disc: domed lens with glowing core and short rays
for (var u = 0; u <= 16; u++) for (var v = EV - 16; v <= EV + 16; v++) {
  var dv = v - (EV + 3), rr = Math.sqrt(u * u + dv * dv);
  var ang = Math.atan2(dv, u) / D2R;
  var ph = ((ang + 90) % 30 + 30) % 30;
  var rayR = 10 + 4.5 * Math.max(0, 1 - Math.abs(ph - 15) / 5);
  if (rr <= 9.5) {
    var h = 1.2 + 3.2 * Math.sqrt(Math.max(0, 1 - rr * rr / 90));
    var t = rr < 4.5 ? 'glowstone' : rr < 7.5 ? 'gold_block' : rr < 8.5 ? 'orange_wool' : 'gold_block';
    col(u, v, CZ + 0.6, h, t);
  } else if (rr <= rayR) {
    col(u, v, CZ + 0.6, 1.0, rr > rayR - 1.5 ? 'orange_wool' : 'yellow_wool');
  }
}
// root joints: small gold/iron knuckles where wings meet the emblem
for (var u = 3; u <= 9; u++) for (var v = 58; v <= 82; v++) {
  var up = v >= 72;
  var dd = up ? Math.abs(v - 79) : Math.abs(v - 64);
  if (dd <= 3 - (u - 3) * 0.3) col(u, v, sweep(u, v), 1.8, up ? 'gold_block' : 'iron_block');
}

// ---------------- emit, grounded at Y=0 ----------------
// prune any stray specks not connected to the main wing body
var seen = {}, best = null;
for (var k0 in G) {
  if (seen[k0]) continue;
  var comp = [], st = [k0]; seen[k0] = 1;
  while (st.length) {
    var c = st.pop(); comp.push(c); var p0 = c.split(',');
    for (var a = -1; a <= 1; a++) for (var b = -1; b <= 1; b++) for (var d = -1; d <= 1; d++) {
      var q = (+p0[0] + a) + ',' + (+p0[1] + b) + ',' + (+p0[2] + d);
      if (G[q] && !seen[q]) { seen[q] = 1; st.push(q); }
    }
  }
  if (!best || comp.length > best.length) best = comp;
}
var keep = {}; for (var i = 0; i < best.length; i++) keep[best[i]] = 1;
for (var k1 in G) if (!keep[k1]) delete G[k1];
var minY = 1e9;
for (var key in G) { var y = +key.split(',')[1]; if (y < minY) minY = y; }
for (var key in G) { var p = key.split(','); block(+p[0], +p[1] - minY, +p[2], G[key]); }
